WITH metrics AS (SELECT *, SUM(units) OVER (ORDER BY revenue, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_units, LAG(revenue, 1) OVER (PARTITION BY product_id ORDER BY sale_date, id) prev_revenue, NTILE(4) OVER (ORDER BY revenue, id) revenue_bucket FROM store_sales) SELECT CASE WHEN revenue >= 3400 THEN 'HIGH' ELSE 'LOW' END AS revenue_tier, ROUND(AVG(revenue_bucket), 2) AS avg_revenue_bucket, COUNT(DISTINCT id) AS distinct_ids FROM metrics GROUP BY CASE WHEN revenue >= 3400 THEN 'HIGH' ELSE 'LOW' END HAVING distinct_ids < 1 ORDER BY revenue_tier DESC;
